operations.before:
// Unlike a Go compiler, we accept statements at top-level to enable
// parsing of partial code snippets in documentation (see #63).
seq($._statement, terminator),

operations.after:
// Go spec "Semicolons": a newline ends a statement only after a token that can end a line.
// src/scanner.c decides that and emits this external token (a symbol reference, since the
// constant is built outside the rules).
const newline = {type: 'SYMBOL', name: '_automatic_semicolon'};
const terminator = choice(newline, ';', '\0');

// Automatic semicolons for tree-sitter-go (Go spec, "Semicolons").
//
// The Go lexer turns a newline (or EOF) into a semicolon when the line's final token is an
// identifier, a basic literal, one of the keywords break, continue, fallthrough and return,
// or one of ++ -- ) ] }. A general comment that contains a newline acts like a newline.
//
// The scanner cannot see the previous token, so it reads it from the parse state:
// - the newline terminator token is valid exactly where a statement, declaration, spec or
//   field has ended; all of these end with such a token;
// - the '||' operator, lexed here, is valid exactly after a complete expression, and every
//   expression ends with such a token.
// In either state a newline is a semicolon. Where only '||' is valid (inside parentheses,
// brackets or braces) the semicolon is a syntax error, as in Go: `f(a` NEWLINE `)`.
// Anywhere else the previous token cannot end a line, and the newline is white space.
#include "tree_sitter/parser.h"

enum TokenType {
  NEWLINE,
  LOGICAL_OR,
  ERROR_SENTINEL,
};

void *tree_sitter_go_external_scanner_create(void) { return NULL; }
void tree_sitter_go_external_scanner_destroy(void *payload) { (void)payload; }
unsigned tree_sitter_go_external_scanner_serialize(void *payload, char *buffer) {
  (void)payload;
  (void)buffer;
  return 0;
}
void tree_sitter_go_external_scanner_deserialize(void *payload, const char *buffer, unsigned length) {
  (void)payload;
  (void)buffer;
  (void)length;
}

static bool scan_logical_or(TSLexer *lexer) {
  if (lexer->lookahead != '|') return false;
  lexer->advance(lexer, false);
  if (lexer->lookahead != '|') return false;
  lexer->advance(lexer, false);
  lexer->mark_end(lexer);
  lexer->result_symbol = LOGICAL_OR;
  return true;
}

bool tree_sitter_go_external_scanner_scan(void *payload, TSLexer *lexer, const bool *valid_symbols) {
  (void)payload;
  bool recovering = valid_symbols[ERROR_SENTINEL];
  bool line_end = !recovering && (valid_symbols[NEWLINE] || valid_symbols[LOGICAL_OR]);

  for (;;) {
    int32_t c = lexer->lookahead;
    if (c == ' ' || c == '\t' || c == '\r' || c == '\f' || c == '\v' || (c == '\n' && !line_end)) {
      lexer->advance(lexer, true);
    } else {
      break;
    }
  }

  if (line_end) {
    if (lexer->lookahead == '\n') {
      lexer->advance(lexer, false);
      lexer->mark_end(lexer);
      lexer->result_symbol = NEWLINE;
      return true;
    }
    if (lexer->eof(lexer)) {
      lexer->mark_end(lexer);
      lexer->result_symbol = NEWLINE;
      return true;
    }
    if (lexer->lookahead == '/') {
      // a general comment with a newline: a zero-width semicolon before the comment
      lexer->mark_end(lexer);
      lexer->advance(lexer, false);
      if (lexer->lookahead != '*') return false;
      lexer->advance(lexer, false);
      bool newline = false;
      while (!lexer->eof(lexer)) {
        int32_t c = lexer->lookahead;
        lexer->advance(lexer, false);
        if (c == '\n') {
          newline = true;
        } else if (c == '*' && lexer->lookahead == '/') {
          if (!newline) return false;
          lexer->result_symbol = NEWLINE;
          return true;
        }
      }
      return false;
    }
  }

  if (valid_symbols[LOGICAL_OR]) return scan_logical_or(lexer);
  return false;
}
